        &lt;img class=&quot;img-link&quot; alt=&quot;Flush the Turd November 3rd&quot; loading=&quot;lazy&quot; decoding=&quot;async&quot; style=&quot;--img-width:100vw&quot; src=&quot;/images/_xmPLQTSeP-604.webp&quot; width=&quot;604&quot; height=&quot;677&quot;&gt;
